/// Removes the item associated with `key` from the queue.
///
/// There must be an item associated with `key`. The function returns the
/// removed item as well as the `Instant` at which it will the delay will
/// have expired.
///
/// # Panics
///
/// The function panics if `key` is not contained by the queue.
///
/// # Examples
///
/// Basic usage
///
/// ```rust
/// use tokio_util::time::DelayQueue;
/// use std::time::Duration;
///
/// # #[tokio::main]
/// # async fn main() {
/// let mut delay_queue = DelayQueue::new();
/// let key = delay_queue.insert("foo", Duration::from_secs(5));
///
/// // Remove the entry
/// let item = delay_queue.remove(&key);
/// assert_eq!(*item.get_ref(), "foo");
/// # }
/// ```
#[track_caller]
pub fn remove(&mut self, key: &Key) -> Expired<T> {
    use crate::time::wheel::Stack as WheelStack;

    let prev_deadline = {
        let elapsed = self.wheel.elapsed;
        let mut found = None;
        let mut level_idx = 0usize;
        while level_idx < crate::time::wheel::NUM_LEVELS {
            if found.is_none() {
                let level = &self.wheel.levels[level_idx];
                if level.occupied != 0 {
                    let now_slot =
                        (elapsed / crate::time::wheel::slot_range(level.level)) as usize;
                    let rotated = level.occupied.rotate_right(now_slot as u32);
                    let zeros = rotated.trailing_zeros() as usize;
                    let slot = (zeros + now_slot) % 64;
                    let range_level = crate::time::wheel::level_range(level.level);
                    let range_slot = crate::time::wheel::slot_range(level.level);
                    let level_start = elapsed - (elapsed % range_level);
                    let mut deadline = level_start + slot as u64 * range_slot;
                    if deadline < elapsed {
                        debug_assert_eq!(level.level, crate::time::wheel::NUM_LEVELS - 1);
                        deadline += range_level;
                    }
                    debug_assert!(
                        deadline >= elapsed,
                        "deadline={:016X}; now={:016X}; level={}; slot={}; occupied={:b}",
                        deadline,
                        elapsed,
                        level.level,
                        slot,
                        level.occupied
                    );
                    let mut prior_ok = true;
                    let mut later = level_idx + 1;
                    while later < crate::time::wheel::NUM_LEVELS {
